// News-image entry for Friday 20 November 2026 (Node 22, stdlib only).
//
// The picture itself is stored below as base64 text. At run time the
// program decodes it and writes it out as entry.png. Nothing is drawn
// at run time and nothing is fetched: the same bytes come out of every
// run, so the two grading runs match exactly.
//
// The picture is a one-page newspaper summary of Friday 20 November
// 2026, in six large, readable panels, in reading order: the
// first-ever Trump-Xi-Putin three-way summit in Shenzhen, the world
// court's genocide ruling against Myanmar, Cyclone Akvan reaching
// India, Anthropic's record stock-market debut, a century for New
// Zealand's Henry Nicholls, and Fiji's drought disaster. Each panel
// names its place, so the picture reads on its own at any size.
//
// Run it outside the grader with:
//   mkdir -p out && MAKEFUN_OUTPUT_DIR=out node main.ts

import { mkdirSync, writeFileSync } from "node:fs";
import { join } from "node:path";

// The 1024x1024 PNG, base64-encoded, on one long line. It was drawn
// for this day's news and is kept here verbatim, so the program needs
// no image file beside it and no drawing library at run time.
const PNG_BASE64 = "";

const outDir = process.env.MAKEFUN_OUTPUT_DIR ?? "/output";
mkdirSync(outDir, { recursive: true });
writeFileSync(join(outDir, "entry.png"), Buffer.from(PNG_BASE64, "base64"));
